function transportSwitchError(){const error=new Error('Bridge transport changed');error.silentTransportSwitch=true;return error}
function clearWsFallbackTimer(){clearTimeout(state.wsFallbackTimer);state.wsFallbackTimer=null}
function rejectWebSocketPending(){for(const pending of state.pending.values())pending.reject(transportSwitchError());state.pending.clear()}
async function postBridge(path,payload){const response=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok)throw createBridgeError(data.error||'Codex bridge request failed',data.code);return data}
function connectSse(){
  if(state.events)return;
  state.transport='sse';state.connected=false;setStatus('connecting','Connecting to Codex');
  const events=new EventSource('/api/events');state.events=events;
  events.onmessage=event=>{try{handle(JSON.parse(event.data))}catch{}};
  events.onerror=()=>{if(state.events===events){state.connected=false;setStatus('connecting','Connecting to Codex')}};
}
function fallbackToSse(ws){
  if(state.transport==='sse'||(ws&&state.ws!==ws))return;
  clearWsFallbackTimer();rejectWebSocketPending();state.connected=false;
  if(ws){ws.onopen=ws.onmessage=ws.onerror=ws.onclose=null;try{ws.close()}catch{}}
  state.ws=null;connectSse();
}
function connect(){
  if(state.transport==='sse'||state.ws)return;
  const proto=location.protocol==='https:'?'wss:':'ws:';
  let ws;
  try{ws=new WebSocket(`${proto}//${location.host}/ws`)}catch{fallbackToSse();return}
  state.transport='ws';state.ws=ws;
  const fallback=()=>fallbackToSse(ws);
  state.wsFallbackTimer=setTimeout(fallback,WS_CONNECT_TIMEOUT_MS);
  ws.onopen=()=>{if(state.ws===ws)setStatus('connecting','Connecting to Codex')};
  ws.onmessage=(event)=>{if(state.ws!==ws)return;try{const message=JSON.parse(event.data);clearWsFallbackTimer();handle(message)}catch{fallback()}};
  ws.onerror=fallback;ws.onclose=fallback;
}
function rpc(method,params={},accountId=state.selectedAccountId){
  const id=state.rpcId++;
  if(state.transport==='sse')return postBridge('/api/rpc',{id,method,params,accountId,runtimeRevision:state.config.runtimeRevision}).then(message=>{if(message.type!=='rpc/result')throw createBridgeError(message.error||'Codex bridge request failed',message.code);return message.result});
  if(state.ws?.readyState===WebSocket.OPEN){try{state.ws.send(JSON.stringify({type:'rpc',id,method,params,accountId,runtimeRevision:state.config.runtimeRevision}));return new Promise((resolve,reject)=>state.pending.set(id,{resolve,reject}))}catch{fallbackToSse(state.ws);return Promise.reject(transportSwitchError())}}
  return Promise.reject(transportSwitchError());
}
function respondToCodex(requestId,result,error,accountId=state.selectedAccountId){
  if(state.transport==='sse')return postBridge('/api/codex/respond',{requestId,result,error,accountId,runtimeRevision:state.config.runtimeRevision});
  if(state.ws?.readyState===WebSocket.OPEN){
    const id=state.rpcId++;
    return new Promise((resolve,reject)=>{
      const timer=setTimeout(()=>{state.pending.delete(id);reject(new Error('Approval response timed out'))},10000);
      state.pending.set(id,{resolve:value=>{clearTimeout(timer);resolve(value)},reject:failure=>{clearTimeout(timer);reject(failure)}});
      try{state.ws.send(JSON.stringify(error?{type:'codex/error',id,requestId,error,accountId,runtimeRevision:state.config.runtimeRevision}:{type:'codex/response',id,requestId,result,accountId,runtimeRevision:state.config.runtimeRevision}))}
      catch{fallbackToSse(state.ws)}
    });
  }
  return Promise.reject(transportSwitchError());
}
function handle(message){
  if(message.type==='thread/account/changed'){applyThreadAccountChange(message.threadId,message.accountId);return;}
  if(message.type==='codex/account-disconnected'&&message.accountId===state.selectedAccountId){approvalEventGeneration++;resolvedApprovalIds.clear();for(const card of state.requestCards.values())card.remove();state.requestCards.clear();syncAccountSelector();return;}
  if(message.type==='codex/account-connected'&&message.accountId===state.selectedAccountId){if(state.active?.id)void restorePendingApprovals(state.active.id,threadNavigationGeneration);scheduleActiveThreadSync(0);return;}
  if(message.type==='auto-reload/changed'){applyAutoReload(message);return;}
  if(message.type==='threads/project-changed'){for(const thread of state.threads)if(thread.id===message.threadId){thread.cwd=message.path;thread.projectless=false}if(state.active?.id===message.threadId){state.active.cwd=message.path;state.active.projectless=false;renderHeader()}sidebarProjectExpansion[message.path]=true;renderThreads();scheduleThreadListRefresh(0);return;}
  if(message.type==='projects/changed'){projectSettings.refresh().catch(error=>toast(error.message));return;}
  if(message.type==='runtime/changed'){accountPanel?.clearUsage();if(!message.preserveThread)localStorage.removeItem(ACTIVE_THREAD_STORAGE_KEY);location.reload();return;}

  if(message.type==='bridge/status'){
    if(message.runtimeRevision&&message.runtimeRevision!==state.config.runtimeRevision){accountPanel?.clearUsage();localStorage.removeItem(ACTIVE_THREAD_STORAGE_KEY);location.reload();return;}
    if(message.status==='connected'){const shouldLoad=!state.connected;state.connected=true;setStatus('connected','Codex connected');if(shouldLoad){resolvedApprovalIds.clear();loadInitial();if(!embeddedChatPanel)requestTaskNotifyPermission()}}
    else{if(state.connected){for(const card of state.requestCards.values())card.remove();state.requestCards.clear();resolvedApprovalIds.clear()}state.connected=false;setStatus('connecting','Connecting to Codex')}
    return;
  }
  if(message.type==='rpc/result'||message.type==='rpc/error'||message.type==='ack'){
    const p=state.pending.get(message.id);if(!p)return;state.pending.delete(message.id);
    message.type==='rpc/error'?p.reject(createBridgeError(message.error,message.code)):p.resolve(message.result);return;
  }
  if(['codex/notification','codex/request','codex/request/resolved'].includes(message.type)&&(message.accountId||state.defaultAccountId)!==state.selectedAccountId){const method=message.payload?.method,threadId=message.payload?.params?.threadId;if(message.type==='codex/notification'&&threadId&&threadId!==state.active?.id&&['turn/started','turn/completed','thread/status/changed'].includes(method))onNotification(method,message.payload.params);return;}
  if(message.type==='codex/notification'){
    const method=message.payload.method,params=message.payload.params||{};
    if(!params.threadId&&(method.startsWith('item/')||method==='turn/started'||method==='turn/completed'||method==='turn/diff/updated'))return;
    onNotification(method,params);
  }
  if(message.type==='codex/request'){
    const request={...message.payload,accountId:message.accountId||state.defaultAccountId};
    if(['item/commandExecution/requestApproval','item/fileChange/requestApproval','item/permissions/requestApproval'].includes(request.method)&&!request.params?.threadId)return;
    approvalEventGeneration++;resolvedApprovalIds.delete(request.id);onServerRequest(request);return;
  }
  if(message.type==='codex/request/resolved'){approvalEventGeneration++;resolvedApprovalIds.add(message.requestId);const card=state.requestCards.get(message.requestId);if(card){setApprovalWaiting(card.previousElementSibling,null,false);card.remove();state.requestCards.delete(message.requestId);syncAccountSelector()}}
}
function applyAutoReload(data){
  if(!data?.threads||typeof data.revision!=='number'||(data.runtimeRevision&&data.runtimeRevision!==state.config.runtimeRevision))return;
  if(state.autoReloadInstance!==data.instanceId){state.autoReloadInstance=data.instanceId;state.autoReloadRevision=-1}
  if(data.revision<state.autoReloadRevision)return;
  state.autoReloadRevision=data.revision;state.autoReload=data.threads;renderThreads();
}
async function autoReloadRequest(path,body){
  const response=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...body,runtimeRevision:state.config.runtimeRevision}),cache:'no-store'}),data=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(data.error||'Impossibile aggiornare AutoReload');
  applyAutoReload(data);return data;
}
async function loadAutoReload(){
  try{
    const response=await fetch('/api/auto-reload',{cache:'no-store'});if(!response.ok)throw new Error('AutoReload non disponibile');applyAutoReload(await response.json());
    if(embeddedChatPanel)return;
    const visible=new Set(state.threads.map(thread=>thread.id)),legacy=notifier.exhaustedIds().filter(id=>visible.has(id)).slice(0,50);
    if(legacy.length){await autoReloadRequest('/api/auto-reload/import',{threadIds:legacy});notifier.removeExhausted(legacy)}
  }catch(error){console.error('AutoReload non disponibile',error)}
}
