let threadAccountRevision=0;const threadAccountRevisions=new Map();
function threadAccount(id,fallback){return localStorage.getItem(`codex-webui-thread-account:${id}`)||fallback||state.defaultAccountId}
function applyThreadAccountChange(threadId,accountId,revision=++threadAccountRevision){
  if(!threadId||!accountId)return;
  threadAccountRevisions.set(threadId,revision);
  localStorage.setItem(`codex-webui-thread-account:${threadId}`,accountId);
  for(const thread of state.threads)if(thread.id===threadId)thread.accountId=accountId;
  if(state.active?.id===threadId){state.active.accountId=accountId;state.selectedAccountId=accountId;syncAccountSelector();accountPanel?.clearUsage();accountPanel?.refreshUsage();scheduleActiveThreadSync(0)}
  renderThreads();
}
async function selectAccount(id,save=true){
  id=id||state.defaultAccountId;
  if(!save){const changed=state.selectedAccountId!==id;state.selectedAccountId=id;syncAccountSelector();if(changed){accountPanel?.clearUsage();accountPanel?.refreshUsage()}return}
  if(accountStartPending||accountSwitchPending||activeTurnId()||state.requestCards.size){syncAccountSelector();return}
  if(!state.active){const changed=state.selectedAccountId!==id;state.selectedAccountId=id;syncAccountSelector();if(changed){accountPanel?.clearUsage();accountPanel?.refreshUsage()}return}
  const threadId=state.active.id,oldAccountId=state.selectedAccountId,navigation=threadNavigationGeneration;
  if(id===oldAccountId){syncAccountSelector();return}
  const pending={threadId};accountSwitchPending=pending;syncAccountSelector();
  try{
    const result=await rpc('host/thread/switchAccount',{threadId,targetAccountId:id},oldAccountId);
    const accountId=result.accountId||id;
    // A newer ownership notification takes precedence over this response.
    const current=threadAccount(threadId,oldAccountId);
    if(current===oldAccountId||current===accountId)applyThreadAccountChange(threadId,accountId);
    if(navigation===threadNavigationGeneration&&state.active?.id===threadId&&state.selectedAccountId===accountId&&result.thread)state.active={...state.active,...result.thread,accountId,turns:state.active.turns};
  }catch(error){if(!error?.silentTransportSwitch)toast(error.message||'Could not change account',5200)}
  finally{if(accountSwitchPending===pending)accountSwitchPending=null;syncAccountSelector()}
}
function syncAccountSelector(){const select=$('#composerAccount'),button=$('#composerAccountButton'),menu=$('#composerAccountMenu');if(!select||!button||!menu)return;select.innerHTML='';menu.innerHTML='';for(const account of state.accounts){const label=account.label||account.email||account.id,option=document.createElement('option');option.value=account.id;option.textContent=label;select.append(option);const row=document.createElement('button');row.type='button';row.className='composer-account-option';row.setAttribute('role','option');row.setAttribute('aria-selected',String(account.id===state.selectedAccountId));const avatar=document.createElement('span');avatar.className='composer-account-avatar';avatar.textContent=label.trim().slice(0,1).toUpperCase();const text=document.createElement('span');text.className='composer-account-option-copy';const name=document.createElement('strong');name.textContent=label;text.append(name);if(account.email&&account.email!==label){const email=document.createElement('small');email.textContent=account.email;text.append(email)}const mark=document.createElement('span');mark.className='composer-account-check';mark.textContent=account.id===state.selectedAccountId?'✓':'';row.append(avatar,text,mark);row.onclick=()=>{selectAccount(account.id);closeComposerAccountMenu();button.focus()};menu.append(row)}if(state.selectedAccountId&&!state.accounts.some(account=>account.id===state.selectedAccountId)){const option=document.createElement('option');option.value=state.selectedAccountId;option.textContent=state.selectedAccountId;select.append(option)}select.value=state.selectedAccountId||'';select.disabled=Boolean(accountStartPending||accountSwitchPending||activeTurnId()||state.requestCards.size);button.disabled=select.disabled;button.title=select.title=select.disabled?'Account cannot be changed while a turn, approval, or account switch is in progress.':state.active?'Change account for this chat':'Choose an account for this new chat';const selected=state.accounts.find(account=>account.id===state.selectedAccountId),label=selected?.label||selected?.email||state.selectedAccountId||'Account';$('#composerAccountLabel').textContent=label;button.querySelector('.composer-account-avatar').textContent=label.trim().slice(0,1).toUpperCase();select.closest('.composer-account-control').hidden=!state.accounts.length;if(button.disabled)closeComposerAccountMenu()}
function closeComposerAccountMenu(){const menu=$('#composerAccountMenu'),button=$('#composerAccountButton');if(menu)menu.hidden=true;if(button)button.setAttribute('aria-expanded','false')}
async function listAccountThreads(){
  const revision=++threadAccountRevision,ids=state.accounts.map(account=>account.id);
  const fetchList=async id=>{try{const result=await rpc('thread/list',{limit:50,sortKey:'recency_at',sortDirection:'desc'},id);return (result.data||[]).map(thread=>({thread,id}))}catch{return []}};
  const results=(await Promise.all((ids.length?ids:[state.selectedAccountId]).map(fetchList))).flat(),unique=new Map();
  for(const {thread,id} of results){
    const accountId=thread.accountId||threadAccount(thread.id,id);
    if(!unique.has(thread.id)||thread.accountId)unique.set(thread.id,{...thread,accountId});
  }
  for(const thread of unique.values()){
    if((threadAccountRevisions.get(thread.id)||0)>revision)thread.accountId=threadAccount(thread.id,thread.accountId);
    else if(thread.accountId){threadAccountRevisions.set(thread.id,revision);if(threadAccount(thread.id,null)!==thread.accountId)applyThreadAccountChange(thread.id,thread.accountId,revision);else localStorage.setItem(`codex-webui-thread-account:${thread.id}`,thread.accountId)}
  }
  return {data:[...unique.values()]};
}
