async function deleteThread(thread){
  if(!thread?.id)return;
  const title=titleOf(thread);
  if(!confirm(t('Delete “{title}”? This permanently deletes the thread and its descendants.',{title})))return;
  try{
    await rpc('thread/delete',{threadId:thread.id},threadAccount(thread.id,thread.accountId));
    const wasActive=state.active?.id===thread.id;
    state.threads=state.threads.filter(item=>item.id!==thread.id);
    await refreshThreadList();
    if(wasActive)startNewTask();else renderThreads();
    toast(t('Thread deleted'));
  }catch(error){
    console.error('Could not delete thread',error);
    if(!confirm('Questa chat ha problemi e non può essere eliminata normalmente. Vuoi rimuoverla dalla lista? La cronologia e le eventuali copie resteranno conservate; questa operazione non interrompe un lavoro ancora in corso.'))return;
    try{
      await rpc('host/thread/hide',{threadId:thread.id},threadAccount(thread.id,thread.accountId));
      const wasActive=state.active?.id===thread.id;
      state.threads=state.threads.filter(item=>item.id!==thread.id);
      await refreshThreadList();
      if(wasActive)startNewTask();else renderThreads();
      toast('Chat rimossa dalla lista');
    }catch(hideError){console.error('Could not hide thread',hideError);toast('Impossibile rimuovere la chat dalla lista')}
  }
}
async function renameThread(thread,value){
  if(!thread?.id)return;
  const name=value.trim();
  if(!name||name===thread.name)return;
  try{
    await rpc('thread/name/set',{threadId:thread.id,name},threadAccount(thread.id,thread.accountId));
    const listed=state.threads.find(item=>item.id===thread.id);
    if(listed)listed.name=name;
    if(state.active?.id===thread.id){state.active.name=name;renderHeader()}
    renderThreads();
  }catch(error){console.error('Could not rename thread',error);toast('Impossibile rinominare la chat')}
}
