function updateComposerAutocomplete(){const input=$('#prompt'),match=getComposerAutocomplete(input.value,input.selectionStart??input.value.length);if(!match){closeComposerAutocomplete();return}autocompleteState.match=match;autocompleteState.selected=0;if(match.type==='slash'){autocompleteState.requestId++;const query=match.query.trim().toLowerCase();autocompleteState.items=slashCommandCatalog.filter(item=>(!item.requiresThread||state.active)&&(item.id.includes(query)||item.title.toLowerCase().includes(query)));autocompleteState.message='';renderComposerAutocomplete();return}searchMentionSuggestions(match)}
function moveComposerAutocomplete(delta){if(!autocompleteState.items.length)return;autocompleteState.selected=(autocompleteState.selected+delta+autocompleteState.items.length)%autocompleteState.items.length;renderComposerAutocomplete()}
function setPlanMode(active){state.planMode=Boolean(active);refreshComposerPlaceholder();syncPermissionControl()}
function applyAutocompleteToken(match,replacement){const input=$('#prompt'),result=applyComposerSuggestion(input.value,match,replacement);input.value=result.text;input.setSelectionRange(result.cursor,result.cursor);resizePrompt()}
function renderContextTray(){const tray=$('#composerContextTray');tray.innerHTML='';for(const mention of state.composerMentions){const chip=document.createElement('div');chip.className='composer-context-chip';chip.dataset.contextId=mention.id;chip.innerHTML=`${codexIcon(mention.icon||'file')}<span>${escapeHtml(mention.title)}</span><button type="button" aria-label="Remove ${escapeHtml(mention.title)}">${codexIcon('x')}</button>`;chip.querySelector('button').onclick=()=>{state.composerMentions=state.composerMentions.filter(item=>item.id!==mention.id);renderContextTray();saveComposerDraft()};tray.append(chip)}tray.hidden=!state.composerMentions.length;syncComposerSubmitState()}
function selectComposerAutocomplete(index=autocompleteState.selected){const item=autocompleteState.items[index],match=autocompleteState.match;if(!item||!match)return;const id=item.id;if(item.source==='action'&&id==='choose-project'){closeComposerAutocomplete();openFolderPicker()}else if(item.source==='file'||item.source==='folder'){applyAutocompleteToken(match,`@${item.path}`);if(!state.composerMentions.some(mention=>mention.id===item.id))state.composerMentions.push({...item});renderContextTray();closeComposerAutocomplete()}else if(item.source==='task'){applyAutocompleteToken(match,`@${item.title}`);if(!state.composerMentions.some(mention=>mention.id===item.id))state.composerMentions.push({...item});renderContextTray();closeComposerAutocomplete()}else{if(id==='init')applyAutocompleteToken(match,'/init');closeComposerAutocomplete();if(id==='plan'){setPlanMode(!state.planMode);$('#prompt').value='';resizePrompt()}else if(id==='model'){ $('#prompt').value='';resizePrompt();openModelMenu()}else if(id==='reasoning'){ $('#prompt').value='';resizePrompt();openModelMenu()}else if(id==='project'){ $('#prompt').value='';resizePrompt();openFolderPicker()}else if(id==='mcp'){ $('#prompt').value='';resizePrompt();toast('MCP status requires the native desktop status surface.')}else if(id==='compact'){ $('#prompt').value='';resizePrompt();toast('Compact requires the native desktop command bridge.')}else if(id==='status'){ $('#prompt').value='';resizePrompt();toast(state.active?.id?`Task ${state.active.id}`:'No active task')}}saveComposerDraft();requestAnimationFrame(()=>$('#prompt').focus())}
async function addComposerImages(files){
  const key=composerDraftKey(state.active?.id||null),images=Array.from(files).filter(file=>/^image\/(png|jpeg|gif|webp|bmp|avif)$/.test(file.type));
  if(!images.length&&files.length)toast('Unsupported image format.');
  for(const file of images){
    const draft=key===composerDraftKey(state.active?.id||null)?state.composerMentions:(readDraftKey(key)?.mentions||[]);
    if(file.size+draft.filter(item=>item.source==='image').reduce((total,item)=>total+(item.size||0),0)>2*1024*1024){toast('Images are too large (maximum 2 MB total).');continue}
    try{const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)});const mention={id:crypto.randomUUID(),source:'image',title:file.name||'Image',icon:'file',url,size:file.size};if(key===composerDraftKey(state.active?.id||null)){state.composerMentions.push(mention);renderContextTray();saveComposerDraft()}else{const draft=readDraftKey(key)||{};writeDraftKey(key,{...draft,mentions:[...(draft.mentions||[]),mention]})}}catch{toast('Could not read image.')}
  }
}
async function addComposerFiles(files){
  const key=composerDraftKey(state.active?.id||null);
  for(const file of Array.from(files)){
    if(file.type.startsWith('image/')){await addComposerImages([file]);continue}
    if(file.size>10*1024*1024){toast('File too large (maximum 10 MB).');continue}
    try{
      const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)});
      const response=await fetch('/api/attachments',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:file.name,data})});
      const result=await response.json();if(!response.ok)throw new Error(result.error||'Upload failed');
      const mention={id:crypto.randomUUID(),source:'upload',title:file.name,icon:'file',path:result.path};
      if(key===composerDraftKey(state.active?.id||null)){state.composerMentions.push(mention);renderContextTray();saveComposerDraft()}else{const draft=readDraftKey(key)||{};writeDraftKey(key,{...draft,mentions:[...(draft.mentions||[]),mention]})}
    }catch(error){toast(error.message||'Could not upload file.')}
  }
}
function handlePromptInput(){resizePrompt();updateComposerAutocomplete();saveComposerDraft()}
function handlePromptKeydown(event){const open=!$('#composerAutocomplete').hidden;if(open){if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();moveComposerAutocomplete(event.key==='ArrowDown'?1:-1);return}if((event.key==='Enter'&&!event.shiftKey)||event.key==='Tab'){event.preventDefault();selectComposerAutocomplete();return}if(event.key==='Escape'){event.preventDefault();closeComposerAutocomplete();return}}if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();$('#composer').requestSubmit()}}
async function resumeActiveThread(){if(!state.active)return null;const resumed=await rpc('thread/resume',{threadId:state.active.id});state.active={...state.active,...resumed.thread};renderHeader();return resumed}
async function submitPrompt(event){
  event.preventDefault();closeComposerAutocomplete();closePermissionMenu();
  if(accountSwitchPending||accountStartPending)return;
  const input=$('#prompt'),text=input.value.trim(),turnId=activeTurnId(),navigation=threadNavigationGeneration;
  let thread=state.active;
  const images=state.composerMentions.filter(item=>item.source==='image'&&item.url);
  const uploads=state.composerMentions.filter(item=>item.source==='upload'&&item.path);
  if(turnId&&!text&&!images.length&&!uploads.length){if(thread)await rpc('turn/interrupt',{threadId:thread.id,turnId});return}
  if(!text&&!images.length&&!uploads.length)return;
  const message=[text,...uploads.map(file=>`Attached file: ${file.path}`)].filter(Boolean).join('\n');
  const turnInput=[...(message?[{type:'text',text:message}]:[]),...images.map(image=>({type:'image',url:image.url}))];
  const accountId=state.selectedAccountId,mentions=state.composerMentions,model=state.selectedModel,effort=$('#effortSelect').value,initialDraftKey=composerDraftKey(thread?.id||null);
  const startingProjectless=state.projectless,cwd=thread?.cwd||$('#projectPath').textContent.replace(/^~/,state.config.home);
  const threadPolicy=permissionThreadPolicy(),turnPolicy=permissionTurnPolicy(cwd);
  input.value='';state.composerMentions=[];renderContextTray();resizePrompt();saveComposerDraft();
  const visible=()=>navigation===threadNavigationGeneration&&state.selectedAccountId===accountId&&(!thread||state.active?.id===thread.id);
  const restoreInput=()=>restoreFailedComposerDraft(thread?.id||null,text,mentions,initialDraftKey);
  const resume=async()=>{const resumed=await rpc('thread/resume',{threadId:thread.id},accountId);thread={...thread,...resumed.thread};if(visible()){state.active=thread;renderHeader()}};
  if(turnId){
    let resumed=false;
    try{if(thread?.canAcceptDirectInput!==true){await resume();resumed=true}if(thread)await rpc('turn/steer',{threadId:thread.id,expectedTurnId:turnId,input:turnInput},accountId)}
    catch(error){let failure=error;if(!resumed&&bridgeErrorCode(error)===THREAD_NOT_FOUND&&thread){try{await resume();await rpc('turn/steer',{threadId:thread.id,expectedTurnId:turnId,input:turnInput},accountId);return}catch(resumeError){failure=resumeError}}restoreInput();if(!failure?.silentTransportSwitch)toast(t(threadInputErrorMessage(failure)),5200)}
    return;
  }
  let optimisticId=null;
  accountStartPending=true;syncAccountSelector();
  try{
    if(!thread){
      const res=await rpc('thread/start',{cwd,model,...threadPolicy,sessionStartSource:'startup'},accountId);
      thread={...res.thread,projectless:startingProjectless,accountId};if(accountId)localStorage.setItem(`codex-webui-thread-account:${thread.id}`,accountId);
      localStorage.setItem(`codex-webui-thread-model:${thread.id}`,JSON.stringify({model,effort}));
      if(!state.threads.some(item=>item.id===thread.id))state.threads.unshift(thread);
      if(navigation===threadNavigationGeneration&&state.selectedAccountId===accountId&&!state.active){state.active=thread;syncAccountSelector();saveThreadModel();rememberActiveThread(thread.id);renderContextUsage();renderHeader();$('#conversation').innerHTML=''}
      renderThreads();
    }else if(thread.canAcceptDirectInput!==true)await resume();
    if(visible()){const optimistic={id:'local-'+Date.now(),type:'userMessage',content:turnInput};optimisticId=optimistic.id;upsertItem(optimistic,'optimistic')}
    await rpc('turn/start',{threadId:thread.id,input:turnInput,model,effort,cwd:thread.cwd,...turnPolicy},accountId);
  }catch(error){if(optimisticId&&visible()){state.items.get(optimisticId)?.remove();state.items.delete(optimisticId)}restoreInput();if(!error?.silentTransportSwitch){toast(t(threadInputErrorMessage(error)),5200)}}finally{accountStartPending=false;syncAccountSelector()}
}
function currentThreadOwners(threads){return threads.map(thread=>({...thread,accountId:threadAccount(thread.id,thread.accountId)}))}
function threadSummarySignature(threads){return JSON.stringify(threads.map(thread=>[thread.id,thread.name,thread.preview,thread.updatedAt,thread.recencyAt,thread.status,thread.cwd,thread.projectless]))}
function applyThreadSummaries(threads){const nextSignature=threadSummarySignature(threads),changed=nextSignature!==threadListSignature;threadListSignature=nextSignature;state.threads=threads;for(const thread of threads)notifier.observeSummary(thread.id,thread.status);const summary=state.active&&threads.find(thread=>thread.id===state.active.id);if(summary){const turns=state.active.turns,oldTitle=titleOf(state.active);state.active={...state.active,...summary,turns};if(titleOf(state.active)!==oldTitle)renderHeader();if(summary.status?.type==='active')scheduleActiveThreadSync(0)}if(changed)renderThreads()}
function scheduleThreadListRefresh(delay=THREAD_LIST_POLL_MS){clearTimeout(threadListTimer);threadListTimer=setTimeout(refreshThreadList,document.visibilityState==='hidden'?Math.max(delay,8000):delay)}
